[归一化后的问题]
在 成都市 的店铺各 SKU 浏览量合计是多少？

[已审查的查询计划]
{
  "assets": [
    {
      "asset": "traffic_daily",
      "join_key": "sku_id"
    },
    {
      "asset": "product",
      "join_key": "sku_id"
    },
    {
      "asset": "shop",
      "join_key": "shop_id"
    }
  ],
  "blocking_issues": [],
  "dimensions": [
    "sku（product.sku_id）"
  ],
  "filters": [
    "店铺所在城市 shop.city = '成都市'（店铺城市，非收货城市）",
    "时间范围：原问题未给出，无法从上下文推断"
  ],
  "grain": "sku",
  "limit": 1000,
  "metrics": [
    {
      "caliber": "SUM(traffic_daily.pv)：页面浏览量，不去重、按次累计；跨日区间可直接累加。",
      "name": "pv"
    }
  ],
  "order_by": [
    "pv DESC"
  ],
  "output_columns": [
    "sku_id",
    "pv"
  ],
  "time_range": {
    "end": null,
    "start": null
  }
}

